    state RES_Covers_Charge {
        enter {
            Pgen_req = 0;
            Pbatt_discharge = 0;
            Pbatt_charge = Ppv + Pw - PL;
            Pspare = 0;
            cutin_LNG = 0;
            cutout_LNG = 1;
            cutin_DG3 = 0;
            cutout_DG3 = 1;
            cutin_DG1 = 0;
            cutout_DG1 = 1;
            cutin_DG2 = 0;
            cutout_DG2 = 1;
