    state Battery_Assist {
        enter {
            Pgen_req = 0;
            Pbatt_discharge = PL - Ppv - Pw;
            Pbatt_charge = 0;
            Pspare = 0;
            cutin_LNG = 0;
            cutout_LNG = 1;
            cutin_DG3 = 0;
            cutout_DG3 = 1;
            cutin_DG1 = 0;
            cutout_DG1 = 1;
            cutin_DG2 = 0;
            cutout_DG2 = 1;
            load_cutout = 0;
        }
    }

    state LNG_Battery_Cover {
        enter {
            Pgen_req = PL - Ppv - Pw - Pbatt_Pmax;
            Pbatt_discharge = Pbatt_Pmax;
            Pbatt_charge = 0;
            Pspare = 0;
            cutin_LNG = 1;
            cutout_LNG = 0;
            cutin_DG3 = 0;
            cutout_DG3 = 1;
            cutin_DG1 = 0;
            cutout_DG1 = 1;
            cutin_DG2 = 0;
            cutout_DG2 = 1;
            load_cutout = 0;
        }
    }

    state LNG_LowSoC_ChargeMargin {
        enter {
            Pgen_req = PL - Ppv - Pw + Pgmax / 5;
            Pbatt_discharge = 0;
            Pbatt_charge = Pgmax / 5;
            Pspare = 0;
            cutin_LNG = 1;
            cutout_LNG = 0;
            cutin_DG3 = 0;
            cutout_DG3 = 1;
            cutin_DG1 = 0;
            cutout_DG1 = 1;
            cutin_DG2 = 0;
            cutout_DG2 = 1;
