            Pbatt_discharge = Pbatt_Pmax;
            Pbatt_charge = 0;
            Pspare = 0;
            cutin_LNG = 1;
            cutout_LNG = 0;
            cutin_DG3 = 1;
            cutout_DG3 = 0;
            cutin_DG1 = 0;
            cutout_DG1 = 1;
            cutin_DG2 = 0;
            cutout_DG2 = 1;
            load_cutout = 0;
        }
    }

    state DG1_LowSoC_ChargeMargin {
        enter {
            Pgen_req = PL - Ppv - Pw + Pd1max / 10;
