        }
    }

    state Overload_Illegal {
        enter {
            Pgen_req = Pgmax + eng3_Pmax + Pd1max + Pd2max;
            Pbatt_discharge = PL - Ppv - Pw - Pgmax - eng3_Pmax - Pd1max - Pd2max;
